#!/usr/bin/env python3
"""Paper v42 (2026-11-01): main text condensed to Scripta's 2,500-word limit (user request), figures and captions unchanged.

Every condensed paragraph of Secs. 2-3 is replaced by a shorter one, and the full original text of those sections is
appended, verbatim, as SM Section S11, so no content is lost (labels removed, equations unnumbered). The Discussion and
Conclusions (Mike's wording) are unchanged. v41 stays as the long version.

  make_condensed_v42.py      writes finalpaper_qe_mechanism_v42_validation[_cubes|_trend|_trend_cubes].tex from v41
"""
import re
from pathlib import Path

MS = Path(__file__).resolve().parent.parent / "manuscript"
BASE = MS / "finalpaper_qe_mechanism_v41_validation.tex"

# (first line, last line) of each condensed block in the v41 base file, 1-indexed, inclusive
BLOCKS = {
    "elastodyn": (175, 239), "dft": (243, 251), "md": (256, 258),
    "stab1": (291, 296), "stab2": (306, 306), "elastic": (318, 320), "sep0": (324, 324), "sep": (334, 336),
}
FULL_TITLES = {"elastodyn": "2.1 Elastodynamic Methods",
               "dft": "2.2 DFT Methods", "md": "2.3 Atomistic simulations of decomposed Fe--Cr",
               "stab1": "3.1 Spinodal stability from demixing free-energy curvature", "stab2": None,
               "elastic": "3.2 Elastic stiffening and elastodynamic mapping to Rayleigh SAW observables",
               "sep0": "3.3 Separating composition trends from spinodal conversion trends", "sep": None}

NEW = {}
# Condensed by deleting sentences and clauses of the v41 text (the user's wording kept wherever possible; user,
# 2026-11-01). The Introduction is unchanged.
NEW["elastodyn"] = r"""Elastic waves in each homogeneous alloy obey the elastodynamic wave equation \cite{du2017facile}:

\begin{equation}
    \rho \frac{\partial^2 u_i}{\partial t^2} = C_{ijkl} \frac{\partial^2 u_k}{\partial x_j \partial x_l}
    \label{eqn:ewe}
\end{equation}

where $C_{ijkl}$ are fourth-order stiffness tensor entries indexed by $i,j,k,l=1,2,3$, $\rho$ is density, and $u$ is the displacement field. On its own, Eq.~\ref{eqn:ewe} describes bulk waves in an unbounded medium. The SAW measured by transient grating spectroscopy (TGS), however, is a Rayleigh wave guided by the free surface. Because crystal orientation is not resolved in the present calculations, we solve this surface problem for the isotropic Voigt--Reuss--Hill (VRH) average of each elastic tensor (Sec.~\ref{sec:analysis}). The Rayleigh velocity is then $v_R = v_s\sqrt{q}$, where $q$ is the root in $0<q<1$ of
\begin{equation}
q^3 - 8q^2 + (24-16\beta)q - 16(1-\beta) = 0, \qquad \beta = v_s^2/v_p^2,
\label{eqn:rayleigh}
\end{equation}
with $v_s=\sqrt{G/\rho}=\sqrt{E/[2(1+\nu)\rho]}$ and $v_p=\sqrt{(B+4G/3)/\rho}$. The SAW frequency is $f_{\mathrm{SAW}} = v_R/\lambda$ with $\lambda = 6.4\,\mu$m, the grating period of our TGS measurements \cite{al2023detecting}. Density is interpolated linearly between \textit{bcc} Fe (7870 kg m$^{-3}$) and Cr (7200 kg m$^{-3}$). The boundary conditions, the calculation of the elastic tensor, and the full text of Sections 2--3 before condensation are given in SM Section S11."""

NEW["dft"] = r"""In order to model the BCC Fe--Cr $\delta$--ferrite solid solution, the special quasirandom structure (SQS) methodology was employed \cite{VandeWalleLiu2013}, with SQS supercells generated by the \texttt{mcsqs} software package within the Alloy Theoretic Automated Toolkit (ATAT).
The Vienna \textit{ab initio} Simulation Package (VASP) \cite{kresse1996vasp} was used to perform the density functional theory (DFT) total energy calculations, which were used to derive the elastic properties as well as the enthalpy of mixing.
Spin--polarized DFT calculations were performed on 40--atom SQS supercells employing $\Gamma$--point sampling of reciprocal space along with a 500 eV planewave cutoff energy, with the Projector--Augmented Wave (PAW) method \cite{kresse1999paw} and the Perdew--Burke--Ernzerhof parameterization \cite{pbe1996} of the Generalized Gradient Approximation (GGA). Calculations were performed at $x_{\mathrm{Cr}} = 0$, 0.20, 0.50, 0.95, and 1.00. The self-consistent field procedure (Fig.~\ref{fig:SCF-loop}) and the independent Quantum ESPRESSO calculations are described in SM Sections S11 and S3."""

NEW["md"] = r"""The spinodal conversion fraction $\phi$ and the corresponding elastic moduli are taken from our earlier atomistic study \cite{al2023detecting} (Sec.~3.7 and Fig.~8 therein). These simulations were performed with LAMMPS \cite{plimpton1995}, not VASP, and include no electronic structure. A $50\times50\times50$ \textit{bcc} cell of 250,000 atoms with equiatomic composition was populated randomly and phase-separated by Monte Carlo atom swaps; intermediate states were produced by converting a fraction of the Fe atoms to Cr and the same fraction of Cr atoms to Fe. The elastic constants of each state were calculated by finite deformation with the Fe--Cr two-band embedded-atom-method (EAM) potential of Bonny \textit{et al.} \cite{bonny2011iron}, for ten alloys generated with different random seeds. On this scale, $\phi=0.5$ is the random homogeneous alloy and $\phi=1$ the fully separated structure. Relaxed cell volumes were not retained, so the density is held at the equiatomic value of 7535 kg m$^{-3}$.

To extend the decomposition series beyond the equiatomic alloy, we repeated the full procedure at twelve compositions from $x_{\mathrm{Cr}}=0.05$ to 0.95 in a $25\times25\times25$ cell (31,250 atoms), preserving the composition, and computed random alloys across composition with the same stiffness procedure and potential. Five alloys with different random seeds were generated per composition, and the figures show their mean and standard deviation. As a check, the same small-cell procedure at 50/50 reproduces the bulk modulus of the original series to within 0.2 GPa at every $\phi$ (SM Fig.~\ref{fig:S_md_validation}). All LAMMPS inputs, random seeds, and potential files are provided in the accompanying repository."""

NEW["stab1"] = r"""The local stability of a binary solid solution is governed by the curvature of its free energy of mixing with respect to composition. Where $\partial^2 \Delta G_{\mathrm{mix}}/\partial x_{\mathrm{Cr}}^2 < 0$, infinitesimal composition fluctuations lower the free energy, and demixing proceeds spontaneously without the need for nucleation barriers. Figure~\ref{fig:free_energy} is evaluated at 298.15 K from the concentration-dependent interaction models that Levesque \textit{et al.} fitted to PWSCF--PAW and SIESTA--NC calculations \cite{levesque2011simple}, $\Omega(x)=(x-a)(bx^2+cx+d)$, together with the ideal configurational entropy $S_{\mathrm{mix}}$. Following the sign convention of that model, we plot the demixing free energy
\begin{equation}
\Delta G_{\mathrm{demix}} = \Omega(x)\,x(1-x) + T S_{\mathrm{mix}} = -\Delta G_{\mathrm{mix}}.
\label{eqn:demix}
\end{equation}
The spinodal criterion $\partial^2 \Delta G_{\mathrm{mix}}/\partial x_{\mathrm{Cr}}^2 < 0$ therefore appears as \emph{positive} curvature, $\partial^2 \Delta G_{\mathrm{demix}}/\partial x_{\mathrm{Cr}}^2 > 0$, in Fig.~\ref{fig:free_energy}b, where three-point numerical second differences fall on the exact curve."""

NEW["stab2"] = r"""Figure~\ref{fig:free_energy}b shows that the homogeneous alloy is unstable for $0.21 \lesssim x_{\mathrm{Cr}} \lesssim 0.75$ in the PWSCF--PAW model (with a second, narrow window at $0.87$--$0.98$); the SIESTA--NC model gives $0.25 \lesssim x_{\mathrm{Cr}} \lesssim 0.99$. Both windows contain the Fe--36Cr alloy in which spinodal decomposition was recently detected through TGS stiffening \cite{rae2026tgs}. At the 748 K aging temperature the CALPHAD assessment of Xiong \textit{et al.} places the chemical spinodal at $x_{\mathrm{Cr}}\approx0.30$--0.71 \cite{xiong2011improved}, so Fe--36Cr lies inside it, close to its Fe-rich edge. Within these windows, elastic and acoustic properties cannot be interpreted assuming a homogeneous solid solution. Instead, any observable elastic response must be understood as emerging from a system that is intrinsically driven toward compositional modulation, providing the foundation for linking free-energy curvature to stiffness evolution and ultimately to ultrasonic observables."""

NEW["elastic"] = r"""To connect thermodynamic instability to experimentally measurable quantities, we compute the cubic elastic tensor across $x_{\mathrm{Cr}}$ and propagate these elastic inputs through the surface boundary-value problem of Sec.~2.1. Although $f_{\mathrm{SAW}}$ depends on the full tensor through $B$ and $G$, we use the longitudinal stiffness $C_{11}$ as a compact index of composition-dependent stiffening (Fig.~\ref{fig:elastic_elastodynamics}a). The fully decomposed MD structures are stiffer than the random alloy at every composition, most strongly at intermediate compositions (e.g., 257.4 versus 247.3 GPa at $x_{\mathrm{Cr}}=0.36$). The present DFT tensors are systematically stiffer than the reference data (e.g., $C_{11}=324$ versus 260 GPa for \textit{bcc} Fe), so we interpret relative trends rather than absolute frequencies; Quantum ESPRESSO calculations at the experimental lattice parameter follow the literature between 30 and 50\% Cr ($C_{11}$ within 11 GPa).

In our earlier study, elastodynamic calculations for pristine CASS over randomly sampled grain orientations defined an ``unallowed'' frequency range, above the highest (pseudo-)SAW frequency and below the bulk-wave frequency, in which no surface mode of the pristine material exists; (P)SAW peaks observed there after aging were attributed to stiffened $\delta$-ferrite \cite{al2023detecting}. Figure~\ref{fig:elastic_elastodynamics}b repeats that calculation for every Fe--Cr tensor. In the (P)SAW branch, no literature tensor up to $x_{\mathrm{Cr}}=0.7$ and none of the MD tensors reaches it, even after full decomposition. Only the stiffest tensors enter it: Cr-rich literature alloys and the present DFT tensors (30\% and 46\% of grains at $x_{\mathrm{Cr}}=0.95$ and 1.0). Frequencies in this range therefore indicate stiffness beyond that of a homogeneous solid solution of $\delta$-ferrite or Fe--36Cr composition, consistent with the stiffer Cr-rich $\alpha'$ regions formed by spinodal decomposition (Fig.~\ref{fig:fsaw_combined}a) and with the peak splitting observed after aging \cite{al2023detecting}. Decomposition stiffens mainly the tetragonal shear modulus $C'$ (by 17--29\% for Fe--36Cr, through the Cr-rich $\alpha'$ phase), which makes weak high-velocity pseudo-SAWs above 665~MHz three to five times more frequent, as in the measured tail (SM Section S9). At the electronic level, the stiffer $C'$ of $\alpha'$ follows the filling of the \textit{bcc} $d$ band \cite{soderlind1993theory}, and the electronic topological transition at $x_c\approx0.08$ (SM Section S6) sets the anomalous moduli of the Fe-rich $\alpha$ phase.

The same shear stiffening links the acoustic signal to embrittlement: decomposition raises $G$ (+11\% for MD Fe--36Cr) while leaving $K$ nearly unchanged ($-1.2\%$), so Pugh's ratio $K/G$ falls by 11\% \cite{pugh1954xcii} in step with the SAW shift, while the cleavage resistance, which scales with $K$, stays fixed. Stiffening therefore shifts the balance from plastic flow towards cleavage, as in the Charpy energies of Ref.~\cite{al2023detecting}, which fall from 88.5~J to 14--24~J for CF8 aged 10{,}000~h at 330--400~$^\circ$C as the SAW splitting grows from 12 to 128--229~MHz (SM Section S9). Within the spinodally unstable composition window, elastic stiffening therefore translates into measurable acoustic signatures, enabling stiffness changes to be inferred non-destructively."""

NEW["sep0"] = r"""While elastic constants vary with chromium concentration even in a homogeneous solid solution, spinodal decomposition introduces an additional, time-dependent microstructural evolution. We therefore report two complementary relationships that isolate these contributions within a unified elastodynamic framework."""

NEW["sep"] = r"""Figure~\ref{fig:fsaw_combined}a shows how chromium partitioning produces stiffening. The Fe--36Cr composition lies near a local minimum of the homogeneous $f_{\mathrm{SAW}}(x_{\mathrm{Cr}})$ curve. Spinodal decomposition moves material toward Fe-rich $\alpha$ and Cr-rich $\alpha'$ compositions (arrows); in both directions the homogeneous-alloy frequency increases. The MD random alloys, an independent classical model, also show a frequency minimum, at $x_{\mathrm{Cr}}\approx0.36$--0.40, even though their $C_{11}$ increases monotonically: the minimum comes from the shear moduli, which control the Rayleigh velocity. $C_{11}$ is therefore a convenient index of stiffening, but the SAW response is governed by shear stiffness.

Figure~\ref{fig:fsaw_combined}b isolates the effect of decomposition at fixed overall composition. For Fe$_{50}$Cr$_{50}$ in the MD (EAM) simulations, $f_{\mathrm{SAW}}$ increases monotonically from 0.469 GHz for the random alloy ($\phi=0.5$) to 0.490 GHz for the fully separated structure ($\phi=1$), an increase of about 4.6\%. Repeating the decomposition at twelve compositions gives frequency increases that are nearly symmetric about the equiatomic composition, from 0.5\% at $x_{\mathrm{Cr}}=0.05$ to 5.0\% at Fe--36Cr and 5.7\% at $x_{\mathrm{Cr}}=0.50$. Stiffening on decomposition is therefore largest within the spinodally unstable window of Fig.~\ref{fig:free_energy}b and nearly vanishes for the dilute alloys at either end; the fully separated state is an idealized limit, so these values bound the stiffening from above. Together, $f_{\mathrm{SAW}}(x_{\mathrm{Cr}})$ captures the baseline elastic response of a homogeneous alloy, and $f_{\mathrm{SAW}}(\phi)$ reflects the additional stiffening associated with progressive spinodal conversion."""


def unlabel(txt):
    """Copy of main-text paragraphs for the SM: no labels (they stay in the main text), unnumbered equations."""
    txt = re.sub(r"\s*\\label\{[^}]*\}", "", txt)
    txt = txt.replace(r"\begin{equation}", r"\begin{equation*}").replace(r"\end{equation}", r"\end{equation*}")
    return txt


def main():
    base = BASE.read_text().split("\n")
    old = {k: "\n".join(base[a - 1:b]) for k, (a, b) in BLOCKS.items()}
    full = [r"\subsection*{S11. Full text of Sections 2--3}",
            "The main text condenses Sections 2--3 to the journal's word limit. Their full text before condensation "
            "follows; equation, figure and section numbers refer to the main text."]
    for k in BLOCKS:
        if FULL_TITLES[k]:
            full.append(rf"\paragraph{{{FULL_TITLES[k]}.}}")
        full.append(unlabel(old[k]))
    sm_add = "\n\n".join(full) + "\n"
    for v in ("", "_cubes", "_trend", "_trend_cubes"):
        src = MS / f"finalpaper_qe_mechanism_v41_validation{v}.tex"
        dst = MS / f"finalpaper_qe_mechanism_v42_validation{v}.tex"
        assert not dst.exists(), dst
        t = src.read_text()
        for k in BLOCKS:
            assert t.count(old[k]) == 1, (v, k)
            t = t.replace(old[k], NEW[k])
        i = t.rindex(r"\end{document}")
        t = t[:i] + "\n" + sm_add + "\n" + t[i:]
        dst.write_text(t)
        print("wrote", dst.name)


if __name__ == "__main__":
    main()
